class Solution {
    public int[] numberGame(int[] nums) {
        List<Integer> l = new ArrayList<>();
        for (int x : nums) l.add(x);
        int[] arr = new int[nums.length];
        int idx = 0;
        while (!l.isEmpty()) {
            int a = Collections.min(l); l.remove(Integer.valueOf(a));
            int b = Collections.min(l); l.remove(Integer.valueOf(b));
            arr[idx++] = b; arr[idx++] = a;
        }
        return arr;
    }
}

